import { NextResponse } from 'next/server'
import type { ApiPost } from '@/lib/types'

type UpdatePostBody = {
  title?: string
  content?: string
}

type PostRouteContext = {
  params: Promise<{ id: string }>
}

export async function GET(_request: Request, { params }: PostRouteContext) {
  const { id } = await params

  const post: ApiPost = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post)
}

export async function PUT(request: Request, { params }: PostRouteContext) {
  const { id } = await params
  const body = (await request.json()) as UpdatePostBody
  const { title, content } = body

  const updatedPost: ApiPost = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost)
}

export async function DELETE(_request: Request, { params }: PostRouteContext) {
  const { id } = await params

  return NextResponse.json({ message: `Post ${id} deleted successfully` })
}

