import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { cache } from 'react'
import { BackButton } from '@/components/BackButton'
import type { Comment, Post } from '@/lib/types'

type BlogPostPageProps = {
  params: Promise<{ id: string }>
}

const getPost = cache(async (id: string): Promise<Post | null> => {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 },
  })

  if (!res.ok) {
    return null
  }

  const post = (await res.json()) as Post

  if (!post?.id) {
    return null
  }

  return post
})

const getComments = cache(async (id: string): Promise<Comment[]> => {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } }
  )

  if (!res.ok) {
    return []
  }

  return (await res.json()) as Comment[]
})

export const revalidate = 300
export const dynamicParams = true

export async function generateStaticParams() {
  const posts = (await fetch('https://jsonplaceholder.typicode.com/posts').then(
    (res) => res.json()
  )) as Post[]

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    return {
      title: 'Not Found - My Blog',
    }
  }

  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params

  let post: Post | null
  let comments: Comment[]

  try {
    ;[post, comments] = await Promise.all([getPost(id), getComments(id)])
  } catch {
    notFound()
  }

  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

